 el.innerHTML=apps[id].render();el.dataset.viewKey=key;if(preserve)el.scrollTop=bodyScroll;
 scroll.forEach(p=>{const x=[...el.querySelectorAll('.web-viewport,.office-workarea,.oa-content,.app-content,.document-area')].find(x=>x.className===p.cls);if(x){x.scrollTop=p.top;x.scrollLeft=p.left;}});
