function openApp(id,detail){if(!apps[id])return;if(id==='doc'&&detail&&!docVisible(detail)){toast('附件尚未授权','请从员工自助申请相关字段。');return;}if(id==='browser'&&detail)navigate(detail);if(id==='sheet'&&detail){state.sheetMode=detail;state.sheetFilter='';}if(id==='doc'&&detail)state.doc=detail;if(id==='oa'&&detail)state.oaPage=detail;if(id==='chat'&&detail&&colleagues[detail])state.chat=detail;if(id==='mail'&&detail){state.selectedMail=detail;state.mailSearch='';state.mailFolder='inbox';}if(wins[id]){refreshApp(id);focusWindow(id);save();return;}const count=Object.keys(wins).length;const width=Math.min(id==='sheet'?1030:id==='notes'?650:id==='break'?760:920,innerWidth-40);const height=Math.min(650,innerHeight-155);const x=Math.max(12,Math.min(innerWidth-width-20,Math.round((innerWidth-width)/2)+count*19));const y=Math.min(28+(count%5)*23,Math.max(12,innerHeight-height-140));const w=document.createElement('article');w.className='window';w.dataset.window=id;w.setAttribute('aria-label',apps[id].name);w.style.cssText=`width:${width}px;height:${height}px;left:${x}px;top:${y}px;z-index:${++z}`;w.innerHTML=`<div class="titlebar"><div class="window-controls"><button class="wc-close" data-action="close" data-app="${id}" aria-label="关闭${apps[id].name}"></button><button class="wc-min" data-action="minimize" data-app="${id}" aria-label="最小化${apps[id].name}"></button><button class="wc-max" data-action="maximize" data-app="${id}" aria-label="最大化${apps[id].name}"></button></div>${appIcon(id,'tiny')}<span class="titlebar-name">${apps[id].name}</span><span class="titlebar-meta">${apps[id].subtitle} · 林见</span></div><div class="app-body">${apps[id].render()}</div>`;$('#windows').append(w);wins[id]=true;if(id==='chat')$('.chat-messages',w).scrollTop=$('.chat-messages',w).scrollHeight;w.addEventListener('pointerdown',()=>focusWindow(id));const bar=$('.titlebar',w);bar.addEventListener('dblclick',e=>{if(!e.target.closest('button'))w.classList.toggle('maximized');});bar.addEventListener('pointerdown',e=>{if(e.target.closest('button')||w.classList.contains('maximized')||innerWidth<700)return;e.preventDefault();bar.setPointerCapture(e.pointerId);const sx=e.clientX,sy=e.clientY,l=w.offsetLeft,t=w.offsetTop;const move=ev=>{w.style.left=Math.max(0,Math.min(innerWidth-w.offsetWidth, l+ev.clientX-sx))+'px';w.style.top=Math.max(0,Math.min(innerHeight-160,t+ev.clientY-sy))+'px';};const up=()=>{bar.removeEventListener('pointermove',move);bar.removeEventListener('pointerup',up);bar.removeEventListener('pointercancel',up);};bar.addEventListener('pointermove',move);bar.addEventListener('pointerup',up);bar.addEventListener('pointercancel',up);});focusWindow(id);save();}
function updateDock(){$$('.dock-btn').forEach(b=>b.classList.toggle('running',!!wins[b.dataset.open]));}
function renderShell(){document.documentElement.style.colorScheme='light';$('#desktop').className=`desktop ${state.theme}`;$('#desktop-icons').innerHTML=['start','files','browser','doc','sheet','ppt','notes','mail','chat','oa','break'].map(id=>`<button class="desktop-shortcut" data-open="${id}" aria-label="打开${apps[id].name}">${appIcon(id)}<span>${apps[id].name}</span></button>`).join('');$('#dock').innerHTML=['start','mail','chat','browser','doc','sheet','ppt','files','notes','oa','break'].map((id,i)=>`${i===6?'<span class="dock-divider"></span>':''}<button class="dock-btn" data-open="${id}" aria-label="${apps[id].name}">${appIcon(id)}</button>`).join('');updateDock();updateWorkWidget();}
