function renderBreak(){const m=state.memory;return `<div class="toolbar"><span class="small">没有紧急事项。休息一会儿吧。</span><span class="spacer"></span><span class="badge">摸鱼不推进剧情时间</span></div><div class="app-content"><div class="kicker">OFF THE CLOCK, FOR A MOMENT</div><h2 class="section-title">茶水间</h2><p class="small muted">不是什么地方都藏着秘密。</p><div class="break-grid"><div class="panel"><div class="row between"><h3>叶子翻翻乐</h3><button class="subtle-link" data-action="memory-reset">重开</button></div><p class="small muted">找到六对图案。${m.moves} 次翻牌，已配对 ${m.matched.length/2}/6。</p><div class="memory-board">${m.deck.map((v,i)=>`<button class="memory-card ${m.open.includes(i)?'open':''} ${m.matched.includes(i)?'matched':''}" data-action="memory-flip" data-index="${i}" aria-label="翻开卡片 ${i+1}" ${m.matched.includes(i)?'disabled':''}>${m.open.includes(i)||m.matched.includes(i)?v:'✧'}</button>`).join('')}</div>${m.matched.length===12?'<p style="margin-top:15px;color:#5b804c">六对齐了。今天的小小胜利。</p>':''}</div><div><div class="panel"><h3>换个心情</h3><div class="row">${[['green','森林'],['warm','暖沙'],['night','暮蓝']].map(([id,title])=>`<button class="wallpaper-choice ${id} ${state.theme===id?'selected':''}" data-action="theme" data-theme="${id}" aria-label="${title}壁纸" title="${title}"></button>`).join('')}</div><div class="button-row"><button class="btn" data-action="music">${musicOn?'关闭':'打开'}雨天白噪声</button></div></div><div class="panel" style="text-align:center"><h3>给自己冲杯咖啡</h3><button class="coffee-button" data-action="coffee" aria-label="冲咖啡">☕</button><p class="small muted">今天第 ${state.coffee} 杯 · 不改变绩效</p></div></div></div><div class="panel"><span class="tiny-label">茶水间留言板</span><p>“有人又拿绿色杯子给绿萝浇水。杯底写着：别用它浇绿萝。”</p><button class="btn" data-action="cup" ${state.cupFound?'disabled':''}>${state.cupFound?'已把杯子放回小雨桌上':'看看绿萝旁边的杯子'}</button><p class="small muted" style="margin-top:10px">生活委员会：大家自觉一点。</p></div></div>`;}
function music(){if(musicOn){audioNodes.forEach(n=>{try{n.stop();}catch{}});audioNodes=[];audioContext?.close();audioContext=null;musicOn=false;}else{try{audioContext=new (window.AudioContext||window.webkitAudioContext)();const buffer=audioContext.createBuffer(1,audioContext.sampleRate*3,audioContext.sampleRate),data=buffer.getChannelData(0);let last=0;for(let i=0;i<data.length;i++){last=(last+.02*(Math.random()*2-1))/1.02;data[i]=last*3;}const source=audioContext.createBufferSource();source.buffer=buffer;source.loop=true;const gain=audioContext.createGain();gain.gain.value=.2;source.connect(gain).connect(audioContext.destination);source.start();audioNodes.push(source);musicOn=true;}catch{toast('当前浏览器暂不支持声音','其他功能不受影响。');}}refreshApp('break');}
