function initial(){return {version:12,started:false,theme:'green',doc:'weekly',docs:{report:D.template},customDocs:{},sheetRows:structuredClone(originalRows),sheetMode:'original',sheetFilter:'',sheetUnique:false,sheetSort:false,formula:'=COUNTA(A2:A6)',formulaResult:'',slide:0,slideNotes:false,report:{titles:['我的工作案例','结果与资料来源','后续安排'],intro:'案例名称：\n工作背景：\n本人完成的工作：',work:'后续安排：',results:'结果：\n资料来源：'},evidence:[],notes:'',selectedMail:'assignment',mailSearch:'',mailFolder:'inbox',extraMails:[],sentMails:[],chat:'xiaoyu',chatDrafts:{},chats:{zhou:[{text:'今天选一件你亲手做过的事，16:00 看稿。Word 或 PPT 都行。'}],xiaoyu:[{text:'早！明天新人培训的案例页我今天整理。你确认自己的部分就好。还有，我的绿杯子又不见了……'}],tang:[{text:'早。费用核对我在做，有哪条工作记录需要查可以告诉我。'}],su:[{text:'早上好。办公用品申请在 OA，转正材料发周衡即可。'}]},chatMemory:{},oaPage:'home',fileSearch:'',coffee:0,cupFound:false,memory:{deck:shuffle(['🌿','🌿','☕','☕','🍋','🍋','📎','📎','🍪','🍪','🌼','🌼']),open:[],matched:[],moves:0},submissions:[],ended:false,training:'pending',arc:{route:'unassigned',closed:false,history:['portal.chengchuan.example'],historyIndex:0},case:{grants:[],read:[],known:{zhou:[],xiaoyu:[],tang:[],su:[],luo:[],shen:[]},report:null,reportVersion:0,reportWithdrawn:false,shared:'0511',trainingSource:'shared',trainingRemoved:false,followup:'xiaoyu',career:'undecided',sentQueries:false,publicHelp:false,actions:[],updates:[],pending:[],luoCorrected:false,luoPromise:false},forms:{}};}
let state;try{state=JSON.parse(localStorage.getItem(KEY));if(state?.version!==12)state={...initial(),...(state?.openingTrial?{openingTrial:state.openingTrial}:{})};}catch{state=initial();}Object.assign(docs,state.customDocs);if(state.case.trainingSource==='report'||state.case.reportWithdrawn){if(!state.case.known.xiaoyu.includes('report'))state.case.known.xiaoyu.push('report');}
