function renderDoc(){if(!docVisible(state.doc))state.doc='weekly';const d=docs[state.doc];remember(state.doc);const body=d.editable?(state.docs[state.doc]??d.body):d.body;return `<div class="toolbar"><select data-change="doc-select" aria-label="选择文档">${Object.entries(docs).filter(([id])=>docVisible(id)).map(([id,d])=>`<option value="${id}" ${id===state.doc?'selected':''}>${esc(d.title)}</option>`).join('')}</select><span class="spacer"></span>${d.editable?'<button class="btn" data-action="submit-open" data-format="doc">发送工作案例</button>':'<span class="badge">共享原件 · 只读</span>'}</div><div class="document-area"><div class="document-paper">${d.editable?`<textarea class="document-editor" aria-label="文档正文" data-input="doc-body">${esc(body)}</textarea>`:esc(body)}</div><div class="button-row">${links(d.links)}${!d.editable?evidenceButton(state.doc):''}</div></div><div class="statusbar"><span>${esc(d.tag)}</span><span>本机保存不会发送</span></div>`;}
function renderSheet(){remember(state.sheetMode==='feedback'?'feedback':'sheet');const s=state,mode=s.sheetMode;
 if(mode==='feedback')return `<div class="app-content"><h2>服务回访记录</h2>${table(['日期','学员','事项','本人反馈','来源'],[['04-07','罗青 / U-0427','资料补发','可打开；“谢谢你们，来回麻烦了。”',links([['mail','luo','原服务邮件']])],['04-12','陈悦 / U-0513','回放入口','可以播放','服务回访记录']])}${evidenceButton('feedback')}</div>${sheetTabs()}`;
 const fields=['id','user','name','date','stage','owner','status','record','feedback'];let rows=mode==='current'?freshCurrent():mode==='original'?originalRows:mode==='copy'?s.sheetRows:s.ui?.books?.[mode]?.rows||[];const base=rows;rows=rows.filter(r=>Object.values(r).join(' ').includes(s.sheetFilter));if(s.sheetSort)rows=[...rows].sort((a,b)=>a.date.localeCompare(b.date));if(s.sheetUnique)rows=rows.filter((r,i,a)=>a.findIndex(x=>x.id===r.id)===i);const ro=['original','current'].includes(mode);
 return `<div class="grid-filter"><span>${mode==='original'?'阶段复盘快照 · 截至 05-11 · 只读':mode==='current'?'当前工作表 · 保留历史动作':'我的可编辑工作表'}</span><input data-input="sheet-filter" aria-label="筛选表格" value="${esc(s.sheetFilter)}" placeholder="筛选姓名、编号或事项"><button class="btn" data-action="sheet-clear">清除</button></div><div class="formula-bar"><span class="cell-address">A2</span><span>ƒx</span><input data-input="formula" aria-label="公式" value="${esc(s.formula)}"><button class="btn" data-action="formula-eval">计算</button><span>${esc(s.formulaResult)}</span></div><div class="sheet-wrap"><table class="sheet-table"><thead><tr><th></th>${['问题编号','学员编号','姓名','提交日期','问题摘要','经办人','本组处理状态','处理记录','最近用户回访'].map((x,i)=>`<th>${String.fromCharCode(65+i)} · ${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td>${base.indexOf(r)+2}</td>${fields.map((f,i)=>`<td ${ro?'':`contenteditable="true" data-grid-row="${base.indexOf(r)}" data-grid-field="${f}"`} data-cell-address="${String.fromCharCode(65+i)}${base.indexOf(r)+2}">${ro&&f==='id'?`<button class="record-link" data-service-record="${base.indexOf(r)}" data-service-mode="${mode}">${esc(r[f])}</button>`:esc(r[f]||'')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${sheetTabs()}<div class="toolbar">${links([['doc','definitions','填写说明']])}${evidenceButton(mode==='current'?'current':'sheet')}<span class="small">显示 ${rows.length} 行 · 点击编号查看完整记录 · 可横向滚动</span></div>`;}
function serviceRecord(index,mode){const r=(mode==='current'?freshCurrent():originalRows)[index];if(!r)return;const labels={id:'问题编号',user:'学员编号',name:'姓名',date:'提交日期',stage:'问题摘要',owner:'经办人',status:'本组处理状态',record:'处理记录',feedback:'最近用户回访'};const contact=Object.keys(colleagues).find(id=>colleagues[id].name===r.owner);modal(`<h2>${esc(r.id)} · 服务事项</h2><dl class="service-detail">${Object.entries(labels).map(([k,n])=>`<dt>${n}</dt><dd>${esc(r[k])}</dd>`).join('')}</dl><div class="button-row">${contact?links([['chat',contact,'联系经办人 '+r.owner]]):''}${r.id==='C-0406-17'?links([['mail','luo','原服务邮件']]):''}${links([['sheet','feedback','服务回访']])}<button class="btn" data-action="modal-close">关闭</button></div>`);}
function sheetTabs(){return `<div class="sheet-tabs">${[['original','服务事项 · 0511快照'],['feedback','服务回访'],['current','当前工作表'],['copy','我的工作副本'],...Object.entries(state.ui?.books||{}).map(([id,b])=>[id,b.name])].map(([id,n])=>`<button class="sheet-tab ${state.sheetMode===id?'active':''}" data-action="sheet-mode" data-mode="${id}">${esc(n)}</button>`).join('')}</div>`;}
function renderPPT(){const i=state.slide,r=state.report,text=i===0?r.intro:i===1?r.results:i===2?r.work:state.ui?.extraSlides?.[i]||'';return `<div class="toolbar"></div><div class="split"><aside class="slide-sidebar">${r.titles.map((t,i)=>`<button class="slide-thumb ${state.slide===i?'active':''}" data-action="slide" data-index="${i}">${esc(t)}<small>${i+1}</small></button>`).join('')}</aside><div class="slide-main"><div class="slide-canvas"><div class="slide-brand">CHENGCHUAN / 工作案例</div><input class="slide-title-input" data-input="slide-title" aria-label="幻灯片标题" value="${esc(r.titles[i])}"><textarea class="slide-textarea" data-input="slide-body" aria-label="幻灯片正文">${esc(text)}</textarea><span class="slide-num">${i+1} / ${r.titles.length}</span></div><div class="slide-form"><p class="small muted">一页也可以提交。保存是本机草稿，提交前会预览实际内容。</p>${links([['doc','weekly','我的工作记录'],['doc','summary','阶段复盘']])}</div>${state.slideNotes?'<div class="slide-notes">写清自己做过的事、当时结果和资料来源；其他页面可留空。</div>':''}</div></div><div class="statusbar"><span>第 ${i+1} 页</span><span>本机草稿</span></div>`;}
function newDoc(copy){const id='new-'+crypto.randomUUID(),old=docs[state.doc];docs[id]={title:copy?old.title+' · 副本':'空白文档',body:copy?(state.docs[state.doc]??old.body):'',editable:true,tag:'我的文件'};state.docs[id]=docs[id].body;state.doc=id;persistCustom();openApp('doc');}
function persistCustom(){state.customDocs=Object.fromEntries(Object.entries(docs).filter(([id])=>id.startsWith('new-')));save();}
function allMails(){return [...state.extraMails,...D.mails].sort((a,b)=>b.time.localeCompare(a.time));}
function stamp(){state.case.minute=Math.max(state.case.minute||547,state.case.report?960:547)+1;return '05-15 '+String(Math.floor(state.case.minute/60)).padStart(2,'0')+':'+String(state.case.minute%60).padStart(2,'0');}
function addMail(id,from,subject,body,links=[]){if(state.extraMails.some(m=>m.id===id))return;state.extraMails.unshift({id,from,who:from==='沈念'?'shen':from==='罗青'?'luo':Object.keys(colleagues).find(k=>colleagues[k].name===from)||null,subject:subject.replace(/^(?:Re: )+/, 'Re: '),body,time:stamp(),links});}
function renderMail(){let items=state.mailFolder==='sent'?state.sentMails:allMails();items=items.filter(m=>[m.subject,m.from,m.body].join(' ').includes(state.mailSearch));const m=items.find(m=>m.id===state.selectedMail)||items[0];if(m){state.selectedMail=m.id;remember(m.id);}return `<div class="toolbar"><button class="btn primary" data-action="mail-compose">写邮件</button>${['inbox','sent'].map((f,i)=>`<button class="btn" data-action="mail-folder" data-folder="${f}">${i?'已发送':'收件箱'}</button>`).join('')}<span class="spacer"></span><input class="field" aria-label="搜索邮件" data-input="mail-search" value="${esc(state.mailSearch)}" placeholder="搜索邮件"></div><div class="split"><aside class="mail-list">${items.map(x=>`<button class="mail-item ${x.id===m?.id?'active':''}" data-action="mail-select" data-id="${x.id}"><small>${esc(x.from)} · ${esc(x.time)}</small><strong>${esc(x.subject)}</strong></button>`).join('')}</aside><div class="app-content">${m?`<div class="mail-header"><h2>${esc(m.subject)}</h2><p>${esc(m.from)} → ${esc(m.toName||'林见')}${m.id==='luo'?'（本封无抄送）':''} · ${esc(m.time)}</p></div><div class="mail-content">${esc(m.body)}</div>${m.history?`<details><summary>历史邮件 · ${m.history.length} 封</summary>${m.history.map(([t,w,b])=>`<section class="thread-history"><b>${t} · ${w}</b><p>${esc(b)}</p></section>`).join('')}</details>`:''}<div class="button-row">${links(m.links)}${evidenceButton(m.id)}</div>${state.mailFolder!=='sent'?`<div class="button-row">${m.who?`<button class="btn" data-action="mail-reply" data-id="${m.id}">回复</button>`:''}<button class="btn" data-action="mail-forward" data-id="${m.id}">转发</button></div>`:''}`:'没有符合条件的邮件。'}</div></div>`;}
function renderFiles(){return `<div class="toolbar"><b>工作文件</b><span class="spacer"></span><button class="btn" data-action="new-doc">新建文档</button></div><input class="field" aria-label="搜索文件" data-input="file-search" value="${esc(state.fileSearch)}" placeholder="搜索文件名"><div class="app-content">${Object.entries(docs).filter(([id,d])=>docVisible(id)&&d.title.includes(state.fileSearch)).map(([id,d])=>`<button class="file-row" data-open="doc" data-detail="${id}">${appIcon('doc','sm')}<div><strong>${esc(d.title)}</strong><small>${esc(d.tag)}</small></div></button>`).join('')}${links([['sheet','original','知禾项目_服务事项_截至0511.xlsx'],['ppt','','转正汇报.pptx']])}</div>`;}
function renderNotes(){return `<div class="app-content"><h2>便签与材料夹</h2><p class="small muted">仅自己可见。收藏、编辑不会通知同事。</p><textarea class="field textarea" data-input="private-notes" aria-label="私人笔记">${esc(state.notes)}</textarea>${state.evidence.map(id=>`<div class="evidence-card">${sourceButton(id)}</div>`).join('')}</div>`;}
function appIcon(id,cls=''){return `<span class="app-icon ${cls}" style="--app-color:${apps[id]?.color||'#608670'}">${icon(id)}</span>`;}
function table(head,rows){return `<div class="web-table-wrap"><table class="web-table"><thead><tr>${head.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function card(title,text,buttons=''){return `<section class="web-card"><h3>${esc(title)}</h3><p>${text}</p><div class="button-row">${buttons}</div></section>`;}
const webRoutes={'portal.chengchuan.example':'工作导航','www.chengchuan.example':'澄川网络科技','class.zhihe.example':'知禾学堂 · 课程归档','project.chengchuan.example':'知禾项目目录','work.chengchuan.example':'我的工作单','training.chengchuan.example':'新人培训待用稿','service.chengchuan.example':'服务记录','help.example':'公共服务咨询（模拟）','cafe.chengchuan.example':'同事生活角'};
function navigate(raw){const u=raw.trim().replace(/^https?:\/\//,'').replace(/\/$/,'');if(state.arc.history[state.arc.historyIndex]!==u){state.arc.history=state.arc.history.slice(0,state.arc.historyIndex+1);state.arc.history.push(u);state.arc.historyIndex++;}}
webRoutes['report.chengchuan.example']='个人汇报 · 后续安排';
function renderBrowser(){const u=state.arc.history[state.arc.historyIndex];return `<div class="browser-tab"><b>${esc(webRoutes[u]||'未收录页面')}</b></div><form class="browser-address" id="browser-form"><button class="btn" type="button" data-action="browser-back" ${state.arc.historyIndex===0?'disabled':''}>←</button><button class="btn" type="button" data-action="browser-forward" ${state.arc.historyIndex===state.arc.history.length-1?'disabled':''}>→</button><input id="browser-url" aria-label="浏览器地址" value="https://${esc(u)}"><button class="btn">前往</button></form><div class="bookmarks">${Object.keys(webRoutes).slice(0,6).map(u=>webLink(u)).join('')}</div><div class="web-viewport">${webPage(u)}</div><div class="statusbar">场景内网页 · 所有公司与收发行为均为虚构模拟</div>`;}
function trainingText(){const c=state.case;if(c.trainingRemoved)return '公开课通知调整案例\n4 月 19 日将 4 月 20 日课程从 19:30 调整为 20:00；页面和补发通知同步更新，经何小雨复核。\n操作演示：核对单节课程日期 → 修改课程页 → 补发通知 → 请同事复核。';if(c.trainingSource==='report'&&c.report&&!c.reportWithdrawn)return state.workdays?.adoptedReport?.text||c.report.text;return c.shared==='0515'?D.revised:D.summary;}
function webPage(u){const c=state.case;switch(u){
 case 'portal.chengchuan.example':return `<div class="portal-heading"><div><span class="eyebrow">CHENGCHUAN / INTRANET</span><h1>今天，做好一件事。</h1><p>2023 年 5 月 15 日 · 运营支持 / 林见</p></div><span class="portal-mark">川</span></div><div class="web-grid">${Object.entries(webRoutes).filter(([u])=>u!=='portal.chengchuan.example').map(([u,n])=>card(n,{'work.chengchuan.example':'转正汇报、培训引用与分工','project.chengchuan.example':'业务范围、人员及资料','training.chengchuan.example':'明天 10:00 的待用材料'}[u]||'工作与生活入口',webLink(u,'进入'))).join('')}</div>`;
 case 'www.chengchuan.example':return `<header class="site-nav"><b>川　澄川网络科技</b>${webLink('portal.chengchuan.example','员工入口')}</header><section class="company-hero"><span>CHENGCHUAN / CONTENT & SERVICE</span><h1>让知识服务<br>有人回应。</h1><p>为线上内容项目提供课程运营、资料整理、通知与用户服务支持。</p></section><div class="web-grid">${card('内容支持','课程页维护、课件更新、直播通知与回放整理。')}${card('用户运营','处理资料与使用问题，登记后续服务需求，协调业务联系人。')}${card('项目协作','汇总服务动作、回访信息与复盘材料，支持国内及境外项目对接。')}</div><p>目前服务项目：知禾学堂。课程实际安排见项目课程页。</p>${webLink('class.zhihe.example')}<footer class="site-footer">澄川网络科技有限公司 · 临澜商务园 B 座 6 层</footer>`;
 case 'class.zhihe.example':return `<h1>知禾学堂 · 4 月课程归档</h1>${table(['日期','主题','时间','资料'],[['04-03','认识家庭现金流','19:30','直播回放已归档'],['04-06','整理收支记录','19:30',links([['doc','lesson','家庭收支示例']])],['04-20','日常预算怎么安排','20:00','时间调整通知：本节由 19:30 改为 20:00，其他课程不变']])}<p>课程服务：澄川课程支持组。后续平台业务由项目联系人另行对接。</p>${links([['mail','schedule','通知留档']])}`;
 case 'project.chengchuan.example':return `<h1>知禾项目目录</h1>${table(['协作范围','人员','联系入口'],[['课程与用户服务','何小雨 / 林见',chatLink('xiaoyu')],['本组工作量核对','唐婧',chatLink('tang')],['项目负责人','周衡',chatLink('zhou')],['境外项目对接','沈念；平台业务联系人陆承',actButton('query','写项目询问')]])}<p>课程材料由国内组维护。平台业务结果由平台方反馈。境外项目组属于协作业务联系人，不在国内人事通讯录中。</p>${links([['doc','summary','阶段复盘_0511'],['sheet','original','服务事项快照'],['oa','org','国内组织架构']])}`;
 case 'service.chengchuan.example':return `<h1>服务记录目录</h1>${links([['sheet','original','截至 05-11 的复盘快照'],['sheet','current','当前工作表'],['sheet','feedback','服务回访']])}<p>复盘快照保留原样，新增回复在当前工作表追加。</p>`;
 case 'training.chengchuan.example':return `<span class="eyebrow">明日 10:00 / 尚未讲授</span><h1>新人培训待用稿</h1><p>整理：何小雨 · 审定：周衡</p><p>来源：${c.trainingRemoved?'公开课通知案例':c.trainingSource==='report'&&!c.reportWithdrawn?'林见个人稿 · 第 '+c.reportVersion+' 版':'阶段复盘_'+c.shared}</p><pre class="case-paper">${esc(trainingText())}</pre><p class="small muted">本页随确认后的引用安排更新。原始复盘与个人稿的提交记录分别留档。</p>${actButton('withdraw','撤回本人稿件引用')}${actButton('remove','请求替换整条培训案例')}${actButton('correct','提出材料更正')}`;
 case 'work.chengchuan.example':return `<h1>我的工作单</h1>${taskRows()}${c.report?card('最近发出的工作案例',`<pre class="case-paper">${esc(c.report.text)}</pre><p>状态：${c.reportWithdrawn?'已撤回，原发送记录保留':'已提交第 '+c.reportVersion+' 版'} · 来源：${esc(c.report.format)}</p><p>所附资料：${c.report.sources.map(sourceName).map(esc).join('、')||'无'}</p>`,actButton('adopt','同意将本稿用于培训')+actButton('withdraw','撤回本稿引用')):''}${card('材料与分工',`<p>共享复盘：${c.shared}。培训稿：${c.trainingRemoved?'已换为课程通知案例':c.trainingSource==='report'&&!c.reportWithdrawn?'采用本人稿':'采用共享复盘'}。</p><p>罗青事项后续负责人：${c.followup==='lin'?'林见（已确认接手记录与转交）':'何小雨'}。境外岗位意向：${careerLabel()}。</p>`,actButton('correct','提出材料更正')+actButton('remove','请求替换整条培训案例')+actButton('follow','确认后续分工')+webLink('training.chengchuan.example','查看实际待用稿'))}<h3>工作往来</h3>${c.actions.map(x=>`<p class="event-row">${esc(x)}</p>`).join('')||'<p>暂无已发送的工作操作。</p>'}`;
 case 'help.example':return `<h1>公共服务咨询 · 游戏内模拟</h1><p>可以记录你掌握的情况和想询问的问题。只附送你选中的材料，不会向现实机关发送内容，也不会通知公司同事。</p>${c.publicHelp?'<p>模拟咨询已留档：目前材料反映服务表述及款项争议，尚需进一步核实。此回复不等于已确认刑事案件或追回款项。</p>':''}${actButton('help','提交模拟咨询')}`;
 case 'cafe.chengchuan.example':return `<h1>同事生活角</h1>${card('午饭拼单','今天食堂有番茄牛腩，何小雨说这次真的不辣。')}${links([['break','','去茶水间']])}`;
 default:return '<h1>此地址未收录在工作浏览器中</h1><p>可以从书签返回公司内网。这里不会访问现实账户或网站。</p>';}}
function taskRows(){const c=state.case;return `<div class="task-item"><h3>16:00 · 转正工作案例</h3><p>${!c.report?'挑一件自己做过的事，写清过程与结果。':c.reportWithdrawn?'已撤回。可以修改后重新提交，也可保留待补状态。':'已收到第 '+c.reportVersion+' 版。下一步：'+(c.trainingSource==='report'?'明日补充本人操作步骤。':c.followup==='lin'?'整理尚待回复的问题，不承诺款项结果。':'确认自己的培训引用范围。')}</p>${links([['doc','report','编辑 Word'],['ppt','','编辑 PPT']])}<button class="btn" data-action="submit-open">预览并提交</button></div><div class="task-item"><h3>16:30 · 运营交接</h3><p>后续分工：${c.followup==='lin'?'林见记录并转交回复；不负责决定款项。':'何小雨继续持有原事项，林见尚未接手。'}</p>${actButton('follow','确认分工')}${webLink('work.chengchuan.example','工作单与发送记录')}</div>`;}
function careerLabel(){return {undecided:'未答复',domestic:'只考虑国内',learn:'仅了解，尚未承诺'}[state.case.career];}
function renderOA(){const p=state.oaPage;let h=p==='tasks'?taskRows():p==='resources'?links([['doc','weekly','我的工作记录'],['doc','summary','项目复盘'],['sheet','original','服务工作簿']]):p==='people'?`<h2>本人工作意向</h2><p>上周周衡提过国内接口与境外常驻协作方向。尚未形成调动安排。</p><p>当前：${careerLabel()}</p>${actButton('career','回复工作方向')}${links([['mail','career','查看原邮件']])}`:p==='announcements'?'<h2>通知公告</h2><p>05-15：明日 10:00 新人培训，讲稿由项目组确认。</p><p>05-12：打印机二号机维护。办公用品可从审批中心申请。</p>':`<h2>早上好，林见</h2><p>2023 年 5 月 ${state.workdays?.day===2?'16':'15'} 日 · 入职第 ${state.workdays?.day===2?'48':'47'} 天 · 运营支持组</p>${taskRows()}`;return `<div class="app-content">${h}</div>`;}
function chatLink(id){return `<button class="btn" data-action="chat-select" data-id="${id}">${colleagues[id].name} ↗</button>`;}
function actButton(action,label){return `<button class="btn" data-case="${action}">${esc(label)}</button>`;}
function grant(id){if(!state.case.grants.includes(id))state.case.grants.push(id);}
function notify(who,text,key){if(key&&state.chats[who].some(x=>x.key===key))return;state.chats[who].push({text,key});}
function known(who,id){return state.case.known[who]?.includes(id);}
function share(who,ids){state.case.known[who]??=[];ids.forEach(id=>{if(!known(who,id))state.case.known[who].push(id);});}
function chatOffers(who){return who==='xiaoyu'?[['record','请求现有对接记录'],['draft','请求当时初稿'],['query','另发一条项目询问']]:who==='tang'?[['finance','请求相关核对邮件']]:who==='zhou'?[['correct','提出材料更正'],['career','回复工作方向'],['follow','确认后续分工']]:[];}
function renderChat(){const who=state.chat,c=colleagues[who];return `<div class="split"><aside class="sidebar"><div class="side-label">同事 · ${Object.keys(colleagues).length}</div>${Object.entries(colleagues).map(([id,p])=>`<button class="nav-item ${id===who?'active':''}" data-action="chat-select" data-id="${id}"><span class="chat-avatar">${p.initial}</span>${p.name}</button>`).join('')}</aside><section class="chat-main"><header class="chat-header">${c.name}<small>${c.role}</small></header><div class="chat-messages" data-person="${who}">${state.chats[who].map(m=>`<div class="chat-message ${m.self?'self':''}"><span class="chat-avatar">${m.self?'见':c.initial}</span><div class="chat-bubble">${esc(m.text)}${links(m.links)}${(m.actions||[]).map(([a,n])=>actButton(a,n)).join('')}</div></div>`).join('')}</div><div class="chat-compose"><details><summary>工作操作</summary><div class="quick-replies">${chatOffers(who).map(([a,n])=>actButton(a,n)).join('')}</div><p class="small muted">聊天可讨论；发出请求、接手和更改稿件需在操作中确认。</p></details><form id="chat-form" class="row"><input id="chat-input" class="field" data-input="chat-draft" aria-label="聊天消息" value="${esc(state.chatDrafts[who]||'')}" placeholder="写下问题，Enter 发送" maxlength="1000"><button class="btn primary">发送</button></form></div></section></div>`;}
function respond(who,raw){const answer=window.replyAsColleague(who,raw,{state,known,careerLabel});state.chatMemory[who].reply=answer;return answer.text;}
function sendChat(text){const t=text.trim();if(!t)return;if(serviceDesk?.isChat(t,state.chat)){state.chatDrafts[state.chat]='';serviceDesk.chat(state.chat,t);return;}serviceDesk?.clearChat();const who=state.chat;state.chatDrafts[who]='';state.chats[who].push({self:true,text:t});const answer=respond(who,t),last=state.chats[who].filter(m=>!m.self).at(-1);if(last?.text!==answer)state.chats[who].push({...state.chatMemory[who].reply,text:answer});else toast('对方暂无新消息','最近的答复仍保留在聊天记录里。');save();refreshApp('chat');$('.chat-messages').scrollTop=$('.chat-messages').scrollHeight;}
function sourceChecks(){
 const recent=[...state.case.read].reverse().filter(id=>!state.evidence.includes(id)&&((docs[id]&&!docs[id].editable&&docVisible(id))||allMails().some(m=>m.id===id)||['sheet','feedback','current'].includes(id)));
 const items=ids=>ids.map(id=>`<label><input type="checkbox" name="sources" value="${esc(id)}"> ${esc(sourceName(id))}</label>`).join('');
 return `<div class="attachment-checks">${items(state.evidence)}${recent.length?`<details ${state.evidence.length?'':'open'}><summary>从最近打开的原件选择（${recent.length}）</summary>${items(recent)}</details>`:''}${!state.evidence.length&&!recent.length?'<p class="small muted">尚未打开或留存材料。可以先查看原件，也可以在正文中写明出处。</p>':''}<p class="small muted">只附送勾选的原件；阅读、收藏和预览都不会发送。</p></div>`;
}
function selectedSources(){return $$('[name="sources"]:checked').map(x=>x.value);}
function reportText(format){if(format==='doc')return state.docs[state.doc]??docs[state.doc]?.body??'';return state.report.titles.map((title,i)=>title+'\n'+(i===0?state.report.intro:i===1?state.report.results:i===2?state.report.work:state.ui?.extraSlides?.[i]||'')).join('\n\n');}
function submitDialog(format){format=format||(activeApp==='doc'?'doc':'ppt');if(format==='doc'&&!docs[state.doc]?.editable){toast('这是一份共享原件','先另存副本或打开自己的汇报模板。');return;}state.forms.submitFormat=format;modal(`<h2>发送工作案例</h2><p>收件人：周衡。以下是本次发送的完整快照。</p><pre class="case-paper">${esc(reportText(format))}</pre><label class="form-label">附送的资料</label>${sourceChecks()}<p class="small muted">只发给周衡；不会自动改动共享复盘或培训稿。</p><button class="btn primary" data-action="submit-report">确认发送</button><button class="btn" data-action="modal-close">继续编辑</button>`);}
function classifyReport(text){const filled=text.split('\n').filter(l=>!/^案例名称[:：]/.test(l)).join('\n').replace(/工作背景|本人完成的工作|后续安排|结果与资料来源|我的工作案例|资料来源|结果|[：:\s]/g,'');if(!filled)return 'empty';if(/19:30|20:00|时间调整|通知.*调整|调整.*通知/.test(text)&&!/罗青/.test(text))return 'ordinary';if(/图表/.test(text)&&/5\s*月?\s*12|05-12/.test(text)&&/交|确认|收到|待/.test(text))return 'routine';if(/尚未|待核|未确认|没有.*(结果|确认)|不.*作.*结论|不能.*(确认|说明)|未.*到账|并不|不代表|不认为|不等于|不应|不是.*解决/.test(text))return 'limited';if(/连续|恢复.*信任|全部.*解决|都.*解决|已经.*(到账|退款)|妥善解决/.test(text))return 'broad';if(/补发|附件/.test(text)&&/回复|打开|收到|反馈|修订版/.test(text))return 'own';return 'unclear';}
function submitReport(){const text=reportText(state.forms.submitFormat),sources=selectedSources(),kind=classifyReport(text);if(kind==='empty'){toast('汇报尚未写入工作内容','模板栏目可以保留，请先补充实际工作。');return;}const c=state.case,signature=JSON.stringify([text,sources]);if(c.report?.signature===signature&&!c.reportWithdrawn){closeModal();toast('这份稿件已发送','如需重交，请先修改正文或附件。');return;}c.reportVersion++;c.report={text,sources,kind,format:state.forms.submitFormat==='doc'?'Word':'PPT',signature};c.reportWithdrawn=false;c.trainingSource=c.trainingSource==='report'?'shared':c.trainingSource;share('zhou',[...sources,'report']);state.submissions.push({to:'zhou',text,sources,version:c.reportVersion});state.sentMails.unshift({id:'report-'+c.reportVersion,from:'林见',toName:'周衡',subject:'转正工作案例 · 第 '+c.reportVersion+' 版',body:text+'\n\n附送：'+sources.map(sourceName).join('、'),time:stamp()});c.actions.push('向周衡提交第 '+c.reportVersion+' 版工作案例。');state.arc.route='review';const reply={ordinary:'通知调整这条过程完整。明天可示范如何同步修改页面与通知。罗青的共享案例仍由小雨处理。',own:'你把自己补资料的过程说清楚了。这部分可以用于个人汇报。共享复盘和培训引用还要各自确认。',limited:'你保留了没有确认的部分。后续可以继续向项目侧核实，也可以只交接给小雨。在确认分工前不算你接手。',broad:'这版可以先留作培训候选。若你同意采用，明天补充你实际做过的步骤；小雨会按已确认的引用安排整理。',unclear:'我收到稿件了，但还看不出是哪件具体工作及当时结果。请补上实际事项再交；这版先留档，暂不作为培训稿。'}[kind];notify('zhou',reply,'report-'+c.reportVersion);addMail('review-'+c.reportVersion,'周衡','Re: 转正工作案例',reply,[['browser','work.chengchuan.example','我的工作单']]);save();closeModal();refreshMany('mail','oa','chat','browser');toast('周衡已回复','工作单和邮箱已更新。');}
const actionInfo={record:['请求现有对接片段','何小雨','只提供 05-09—05-10 的历史记录，不发送新的项目询问。'],draft:['请求当时的案例初稿','何小雨','请求本人写过的原稿。'],finance:['请求复盘核对邮件','唐婧','仅提供与罗青案例有关的往来节选。'],query:['发送项目询问','沈念；抄送周衡、何小雨','项目询问是一次新发送。既有对接片段可以先向小雨索取。'],correct:['提出材料更正','周衡；抄送何小雨','写明要调整的具体表述、范围及出处。这里只处理你发出的请求，不改本地草稿。'],remove:['请求替换培训案例','周衡、何小雨','明日培训不再采用罗青这条，改用课程通知案例。共享复盘原件仍保留。'],withdraw:['撤回本人稿件引用','周衡、何小雨','撤回你个人稿件的培训引用；共享复盘的引用安排独立保留。'],adopt:['确认采用个人稿','周衡、何小雨','采用你最近实际发出的版本，不读取尚未发送的草稿。'],follow:['确认后续分工','周衡、何小雨','明确是否接手记录与转交，不包含决定或保证款项结果。'],career:['回复工作方向','周衡','个人工作意向与转正案例、客户跟进分别确认。'],help:['提交模拟咨询','公共服务咨询页面','只发送所选材料，不通知公司。全部是游戏内模拟。']};
function actionDialog(a){if(!actionInfo[a])return;const [title,to,desc]=actionInfo[a];const required=['query','correct','help'].includes(a);modal(`<h2>${title}</h2><p>收件人：${to}</p><p>${desc}</p>${a==='follow'?'<label class="form-label">本次分工</label><select class="field" id="case-choice"><option value="xiaoyu">我只做交接，后续由何小雨负责</option><option value="lin">我负责记录问题并转交回复，不保证款项结果</option></select>':a==='career'?'<select class="field" id="case-choice"><option value="domestic">只考虑国内工作，拒绝境外常驻</option><option value="learn">可以了解，但不代表接受</option><option value="undecided">暂不答复，保留未决定</option></select>':''}${required?`<label class="form-label">${a==='query'?'需要对方回复的具体问题':'说明'}</label><textarea id="case-note" class="field textarea" placeholder="写下你自己的具体问题或说明">${esc(state.forms[a]||'')}</textarea><label class="form-label">附送材料</label>${sourceChecks()}`:''}<div class="button-row"><button class="btn primary" data-case-confirm="${a}">确认发送</button><button class="btn" data-action="modal-close">暂不发送</button></div>`);}
function act(a){const c=state.case,note=$('#case-note')?.value.trim()||'',sources=selectedSources(),choice=$('#case-choice')?.value;if(['query','correct','help'].includes(a)&&note.length<4){toast('请写明具体事项');return;}const signature=JSON.stringify([a,note,sources,choice,c.reportVersion,c.shared,c.trainingRemoved]);if(!['follow','career'].includes(a)&&c.pending.includes(signature)){closeModal();toast('同一操作已处理','结果在工作往来中保留。');return;}let log='',reply='';const sentTime=stamp();
 if(['record','draft','finance'].includes(a)){if(c.grants.includes(a)){closeModal();openApp('doc',a==='record'?'transfer':a);return;}grant(a);const id=a==='record'?'transfer':a,who=a==='finance'?'tang':'xiaoyu';state.chats[who].push({text:a==='record'?'这段是当时的对接，只截了罗青这一条。没有另发询问。':'相关原件给你了，时间和参与人都在里面。',links:[['doc',id,docs[id].title]]});log='取得'+docs[id].title;}
 if(a==='query'){share('shen',sources);share('zhou',sources);share('xiaoyu',sources);c.sentQueries=true;const personal=/人身|被困|安全|自由|园区|护照/.test(note),money=/钱|款|进度|到账|转回|结果/.test(note);reply=[money?'罗青这条我收到后已经交陆承。这里没有新的到账结果，后续回复从平台业务端出。':'我负责项目对接。请把具体事项和要确认的内容写明，我按事项转交。',personal?'关于我个人的情况，我现在没法在这个账号谈自己的事。':''].filter(Boolean).join('\n\n');addMail('query-'+c.pending.length,'沈念','Re: 罗青事项询问',reply);c.updates.push({id:'C-0509-12',user:'U-0427',name:'罗青',date:'05-15',stage:'项目侧追问',owner:'林见',status:'已发送询问',record:'沈念：已转陆承，无新到账结果',feedback:'—'});log='向沈念发送询问，抄送周衡、何小雨；没有据此接手后续。';}
 if(a==='correct'){share('zhou',sources);share('xiaoyu',sources);const colloquialScope=/感谢|谢谢/.test(note)&&/四月|上个月|4月/.test(note)&&/五月|这月|钱|两万|款/.test(note)&&/别|不要|不该|不能|分开|单独/.test(note);const concrete=colloquialScope||(/感谢|谢谢|引用/.test(note)&&/4.?7|04-07|资料|补发|范围|过去/.test(note))||(/转交|接收/.test(note)&&/结果|解决|到账|确认|范围/.test(note))||(/资料|补发/.test(note)&&/平台|款项|范围|后续|分开/.test(note));if(!concrete){reply='我收到更正意见了。请指出要改的那句话、事项范围或资料出处，目前这份请求还不能直接落到稿件。';addMail('correction-question-'+c.pending.length,'周衡','Re: 材料更正意见',reply);log='提出更正，周衡要求补充具体表述，原稿暂未变化。';}else{c.shared='0515';docs.revised={title:'知禾项目阶段复盘_0515_修订',body:D.revised,tag:'共享 / 05-15 修订，旧版留档',links:[['doc','summary','查看 05-11 原件'],['sheet','feedback','服务回访记录']]};if(c.trainingSource==='report')c.trainingSource='shared';reply='那把案例范围收回到你实际补资料的那次。小雨另存修订版，原稿保留。后续服务另行跟进，不写进已解决的结果。';notify('zhou',reply,'correct-0515');notify('xiaoyu',c.trainingRemoved?'共享修订版已另存。培训仍用课程通知案例，不把罗青放回去。':'共享修订版已另存，培训待用稿同步改用这版。只保留 4 月补发资料，不代表钱已经处理好。','correct-0515');addMail('correct-0515','何小雨','材料更正已更新',reply,[['doc','revised','修订版'],['browser','training.chengchuan.example','培训待用稿']]);log='共享复盘另存为 0515 修订版；'+(c.trainingRemoved?'培训继续使用课程通知案例。':'培训引用同步收窄到资料补发。');}}
 if(a==='adopt'){if(!c.report||c.reportWithdrawn||c.report.kind==='unclear'){toast('暂无可采用的已确认稿件','请先发送完整的工作案例。');return;}if(c.trainingRemoved){toast('罗青案例已从培训撤下','如需恢复引用需要另行讨论，不会自动放回。');return;}c.trainingSource='report';share('xiaoyu',['report']);notify('xiaoyu','收到，培训待用稿采用你第 '+c.reportVersion+' 版。明天请补充本人操作步骤。','adopt-'+c.reportVersion);log='确认采用个人稿第 '+c.reportVersion+' 版。明日任务：补充操作步骤。';}
 if(a==='withdraw'){if(!c.report){toast('还没有发出的个人稿');return;}c.reportWithdrawn=true;share('xiaoyu',['report']);if(c.trainingSource==='report')c.trainingSource='shared';notify('xiaoyu',c.trainingRemoved?'你的个人稿已撤回。培训仍用课程通知案例。':'你的个人稿已撤回，培训继续按共享复盘_'+c.shared+' 整理。','withdraw-'+c.reportVersion+'-'+c.shared);log='撤回第 '+c.reportVersion+' 版本人稿件；共享材料未被撤回。';}
 if(a==='remove'){if(c.trainingRemoved){closeModal();toast('培训已使用替代案例');return;}c.trainingRemoved=true;notify('xiaoyu','那我换成 4 月课程通知调整。罗青这条不放进明天培训，原复盘文件仍留档。','remove');log='明日培训改为课程通知调整案例。';}
 if(a==='follow'){if(c.followup===choice&&c.actions.some(x=>x.startsWith('确认分工：'))){closeModal();toast('当前分工已经如此');return;}c.followup=choice;notify('zhou',choice==='lin'?'确认由你记录问题并转交回复。不要代平台承诺结果；已有材料按原件留存。':'确认你只交接，小雨继续跟。你的转正案例照常处理。','follow-'+choice+'-'+c.pending.length);notify('xiaoyu',choice==='lin'?'我把现有记录交你，后续新回复请追加时间和来源。':'明白，罗青事项我继续跟。你收到的新信可以单独转给我。','follow-'+choice+'-'+c.pending.length);log='确认分工：'+(choice==='lin'?'林见负责记录与转交。':'何小雨继续负责，林见未接手。');}
 if(a==='career'){if(c.career===choice){closeModal();toast('当前意向已经如此');return;}c.career=choice;notify('zhou',choice==='domestic'?'知道了，只考虑国内。今天的汇报照常做，客户跟进另行确认。':choice==='learn'?'先给你留作了解，不算接受外派。具体工作还需以后单独谈。':'那先保留未答复，不替你确认。','career-'+choice);log='工作意向更新：'+careerLabel()+'。';}
 if(a==='help'){c.publicHelp=true;reply='咨询记录已留存。现有材料需要进一步核实，不能据此确认境外地点、资金去向或追回款项。';addMail('help-'+c.pending.length,'公共服务咨询（模拟）','咨询收件记录',reply);log='提交了一份模拟咨询，公司同事未收到通知。';}
 c.pending.push(signature);if(log)c.actions.push(log);if(['query','correct','help'].includes(a))state.sentMails.unshift({id:'action-'+c.pending.length,from:'林见',toName:actionInfo[a][1],subject:actionInfo[a][0],body:note+'\n\n附送：'+sources.map(sourceName).join('、'),time:sentTime});save();closeModal();refreshMany('chat','browser','oa','mail','doc','files','sheet');toast('已处理',log||reply);}
function compose(prefill={}){if(!Object.keys(prefill).length)prefill=state.mailDraft||{};state.mailDraft={...prefill};const options={...Object.fromEntries(Object.entries(colleagues).map(([id,c])=>[id,c.name])),luo:'罗青',shen:'沈念（境外项目对接）'};modal(`<h2>${prefill.forward?'转发原邮件':'写邮件'}</h2><label class="form-label">收件人</label><select id="compose-to" class="field">${Object.entries(options).map(([id,n])=>`<option value="${id}" ${prefill.to===id?'selected':''}>${n}</option>`).join('')}</select><label class="form-label">主题</label><input class="field" id="compose-subject" value="${esc(prefill.subject||'')}"><label class="form-label">正文</label><textarea class="field textarea" id="compose-body">${esc(prefill.body||'')}</textarea>${prefill.forward?`<p>随信转发原件：${esc(sourceName(prefill.forward))}</p>`:''}<label class="form-label">另附材料</label>${sourceChecks()}<p class="small muted">收到邮件不代表同意接手或修改共享文件。相关工作操作另行确认。</p><button class="btn primary" data-action="mail-send">发送</button><button class="btn" data-action="modal-close">暂不发送</button>`);}
function luoReply(text,sources){const c=state.case;let replies=[];if(/为什么.*(?:找|联系)|以为|哪家公司|课程.*平台.*关系|谁.*介绍/.test(text)){replies.push('我是从你们的课认识小雨的，是她介绍我去找平台联系人。我当时以为还是同一个项目的后续服务，所以有问题又回来找课程客服。具体是哪家公司负责账户，我说不清；你们给我介绍时也没有给我一个能处理这笔申请的国内联系人。');}
 if(sources.includes('summary')){share('luo',['summary']);replies.push('这段“谢谢”是 4 月资料能打开时说的，不是后来款项处理好了。我没有说过现在的问题解决了。请不要拿它说我恢复了信任。');}
 if(sources.includes('revised')){c.luoCorrected=true;share('luo',['revised']);replies.push('这版把资料和后面的事分开了，我知道了。款项申请我仍然需要具体回复。');}
 if(/说错|收回|不能保证|无法保证|不.*保证/.test(text)){c.luoPromise=false;replies.push('好，那请按你实际知道的说。你刚才的保证我已收到，现在记下你撤回了。请给我一个负责的联系人。');}
 else if(/肯定.*(到|回来)|已经.*(退|到)|保证.*(到|退|回来)/.test(text)){c.luoPromise=true;replies.push('你说已经处理了，依据是什么？我这边还没有到账。请把实际结果和负责人的回复发给我，别再让我只等。');}
 if(/经过|怎么|课程|发生|多少|平台|银行|资料|记录|款项/.test(text)&&!/说错|收回/.test(text)){const hadAccount=c.grants.includes('account');grant('account');replies.push(hadAccount?'经过和金额已经写在之前的补充说明里，银行还没回复，款项也没有新结果。如果你拿到负责人的具体答复，再发给我。':'我把之前说过的情况整理成附件给你。5 月 11 日已经自己给临序银行发了查询，还没有回复。现在我只想知道 5 月 8 日那笔两万的申请谁负责。');}
 if(/不负责|不接|找.*小雨|转交/.test(text))replies.push('可以交接，但请告诉我实际接收的人。之前已经转过一次，我需要具体回复。');
 if(!replies.length)replies.push(c.luoCorrected?'材料表述更正我已经知道了。款项没有新结果，请告诉我实际负责人的回复。':known('luo','summary')?'摘要里的引用问题我已经说清楚。请不要把资料那次谢谢当作这次款项处理好了。':'我问的是申请转回的两万，现在还是没到。请给我一个具体负责人和回复。');return replies.join('\n\n');}
function sendMail(){const to=$('#compose-to').value,subject=$('#compose-subject').value.trim(),body=$('#compose-body').value.trim(),forward=state.mailDraft?.forward;const sources=[...new Set([...selectedSources(),...(forward?[forward]:[])])];if(!subject||!body){toast('请填写主题和正文');return;}const signature=JSON.stringify([to,subject,body,sources]);if(state.sentMails.some(x=>x.signature===signature)){closeModal();toast('相同邮件已经发送','请查看已发送与回复记录。');return;}share(to,sources);if(to==='xiaoyu'&&sources.includes('luo')&&!state.case.updates.some(r=>r.record==='收到 05-12 本人回信：申请转回的两万未到'))state.case.updates.push({id:'C-0509-12',user:'U-0427',name:'罗青',date:'05-15',stage:'本人补充来信',owner:'何小雨',status:'待项目回复',record:'收到 05-12 本人回信：申请转回的两万未到',feedback:'来源：林见转发的本人邮件'});const id='sent-'+crypto.randomUUID();state.sentMails.unshift({id,signature,from:'林见',toName:colleagues[to]?.name||(to==='shen'?'沈念':'罗青'),subject,body:body+(forward?'\n\n——转发原件——\n'+(allMails().find(x=>x.id===forward)?.body||''):''),time:stamp()});let reply;
 if(to==='luo')reply=luoReply(body,sources);else if(to==='shen'){state.case.sentQueries=true;reply='罗青事项已经交陆承。这里没有新的到账结果，后续从平台业务端回复。'+(/人身|被困|安全|园区/.test(body)?'关于我个人的情况，我现在没法在这个账号谈自己的事。':'');}else if(sources.includes('luo')){reply=to==='xiaoyu'?'这封 5 月 12 日新信我现在收到了。她说两万仍没到。我之前只有转交记录。'+(state.case.followup==='lin'?'目前由你记录与转交，这次转信没有更改分工。':'我按现有分工继续跟，你没有因此接手。'):to==='zhou'?'这封新信我现在收到了。先别代平台保证时间。可以确认由谁继续跟；你也可以只交接给小雨。':'新信收到了，但我不持有她个人到账的记录。需要项目侧给具体回复。';notify(to,reply);}else reply=respond(to,body);
 addMail('reply-'+id,colleagues[to]?.name||(to==='shen'?'沈念':'罗青'),'Re: '+subject,reply,to==='luo'&&state.case.grants.includes('account')?[['doc','account','罗青补充说明_0515']]:[]);state.mailDraft=null;save();closeModal();refreshMany('mail','chat','files','sheet');toast('邮件已发送','回复已保留在收件箱。');}
function endDay(){modal(`<h2>${state.ended?'今日记录':'下班前的交接'}</h2><p>${state.case.report?'工作案例已发送 '+state.case.reportVersion+' 版'+(state.case.reportWithdrawn?'，最近一版已撤回':'')+'。':'转正案例尚未提交，保留为待补；草稿不会代你发送。'}</p><p>培训待用稿：${state.case.trainingRemoved?'课程通知案例':state.case.trainingSource==='report'&&!state.case.reportWithdrawn?'你的个人稿':'共享复盘_'+state.case.shared}。</p><p>后续负责人：${state.case.followup==='lin'?'林见负责记录与转交':'何小雨'}。工作意向：${careerLabel()}。</p><p>${state.case.followup==='lin'?'明日任务：汇总待回复的问题；没有任何到账保证。':state.case.trainingSource==='report'?'明日任务：补充培训采用的个人操作步骤。':'明日任务：按当前分工继续课程与用户服务。'}</p><p class="small muted">第一天到此结束，未处理的邮件和事项继续保留。这里不是整个案件的结局。</p><button class="btn primary" data-action="end-confirm">保存今日记录</button><button class="btn" data-action="modal-close">继续使用电脑</button>`);}
function help(){modal('<h2>你的公司电脑</h2><p>从任务邮件或 OA 待办开始。可以自由打开文件、编辑文档、整理表格、写 PPT，也可以喝咖啡和翻牌。没有隐藏倒计时。</p><p>保存只留在本机；发送窗口会显示收件人。聊天讨论不等于同意接手、变更岗位或修改材料。工作操作在确认发送后生效。</p><div class="button-row"><button class="btn" data-action="replay-prologue">重看序幕</button><button class="btn" data-action="export">导出存档</button><button class="btn" data-action="import">导入存档</button><button class="btn danger" data-action="reset-confirm">重新开始</button><button class="btn" data-action="modal-close">返回</button></div>');}
function exportSave(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state)],{type:'application/json'}));a.download='澄川_罗青第一天存档.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function importSave(){const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{try{const next=JSON.parse(await input.files[0].text());if(next.version!==12||!next.case||!next.chats||!Array.isArray(next.case.actions)||!Array.isArray(next.evidence)||!next.report?.titles||!next.memory?.deck||!next.docs)throw Error();localStorage.setItem(KEY,JSON.stringify(next));location.reload();}catch{toast('存档格式不兼容','当前仅支持罗青案例版存档，现有进度未改变。');}};input.click();}
document.addEventListener('click',e=>{
 const opener=e.target.closest('[data-open]');if(opener){if(opener.closest('#modal-root'))closeModal();openApp(opener.dataset.open,opener.dataset.detail);return;}
 const sr=e.target.closest('[data-service-record]');if(sr){serviceRecord(Number(sr.dataset.serviceRecord),sr.dataset.serviceMode);return;}const ac=e.target.closest('[data-case]');if(ac){actionDialog(ac.dataset.case);return;}
 const confirm=e.target.closest('[data-case-confirm]');if(confirm){act(confirm.dataset.caseConfirm);return;}
 const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
 switch(a){case 'start':prologue.finish();break;case 'modal-close':closeModal();break;case 'replay-prologue':closeModal();prologue.show(state.started);break;
 case 'close':$(`[data-window="${b.dataset.app}"]`)?.remove();delete wins[b.dataset.app];if(activeApp===b.dataset.app)activeApp=null;updateDock();break;case 'minimize':$(`[data-window="${b.dataset.app}"]`).classList.add('minimized');break;case 'maximize':$(`[data-window="${b.dataset.app}"]`).classList.toggle('maximized');break;
 case 'evidence':collect(b.dataset.id);break;case 'new-doc':newDoc(false);break;case 'doc-copy':newDoc(true);break;case 'doc-save':save();toast('已保存');break;
 case 'doc-find':{const q=$('#doc-search')?.value||'',body=state.docs[state.doc]??docs[state.doc].body;const n=q?body.split(q).length-1:0;$('#doc-search-result').textContent='找到 '+n+' 处';const ed=$('.document-editor');if(ed&&n){ed.focus();const at=body.indexOf(q);ed.setSelectionRange(at,at+q.length);}break;}
 case 'sheet-sort':state.sheetSort=!state.sheetSort;refreshApp('sheet');break;case 'sheet-unique':state.sheetUnique=!state.sheetUnique;refreshApp('sheet');break;case 'sheet-clear':state.sheetFilter='';state.sheetUnique=false;refreshApp('sheet');break;case 'sheet-mode':state.sheetMode=b.dataset.mode;state.sheetFilter='';refreshApp('sheet');break;
 case 'sheet-analyze':state.formulaResult=`${originalRows.length} 条事项记录；${new Set(originalRows.map(r=>r.user)).size} 位学员`;refreshApp('sheet');break;
 case 'formula-eval':{const f=state.formula.toUpperCase().trim(),rows=workspaceUI.currentRows(),fields=['id','user','name','date','stage','owner','status','record','feedback'];const range=f.match(/([A-I])(\d+):([A-I])(\d+)/);let values=[];if(range&&range[1]===range[3]){const field=fields[range[1].charCodeAt(0)-65];values=rows.slice(Math.max(0,Number(range[2])-2),Math.max(0,Number(range[4])-1)).map(r=>r[field]).filter(x=>x!==''&&x!==undefined);}if(/^=COUNTA\(UNIQUE\([A-I]\d+:[A-I]\d+\)\)$/.test(f))state.formulaResult=String(new Set(values).size);else if(/^=COUNTA\([A-I]\d+:[A-I]\d+\)$/.test(f))state.formulaResult=String(values.length);else if(/^=SUM\([A-I]\d+:[A-I]\d+\)$/.test(f))state.formulaResult=String(values.reduce((a,n)=>a+(Number(n)||0),0));else if(/^=SUM\([\d.,\s+-]+\)$/.test(f))state.formulaResult=String(f.slice(5,-1).split(',').reduce((a,n)=>a+Number(n),0));else state.formulaResult='支持 COUNTA(A2:A6)、COUNTA(UNIQUE(A2:A6))、SUM(1,2,3)';refreshApp('sheet');break;}
 case 'slide':state.slide=Number(b.dataset.index);refreshApp('ppt');break;case 'ppt-save':toast('演示已保存');break;case 'ppt-notes':state.slideNotes=!state.slideNotes;refreshApp('ppt');break;case 'submit-open':submitDialog(b.dataset.format||(activeApp==='doc'?'doc':activeApp==='ppt'?'ppt':undefined));break;case 'submit-report':submitReport();break;
 case 'mail-select':state.selectedMail=b.dataset.id;refreshApp('mail');break;case 'mail-folder':state.mailFolder=b.dataset.folder;state.mailSearch='';refreshApp('mail');break;case 'mail-compose':compose();break;
 case 'mail-reply':case 'mail-forward':{const m=allMails().find(m=>m.id===b.dataset.id);compose({to:a==='mail-forward'?'xiaoyu':m.who,subject:(a==='mail-forward'?'Fwd: ':'Re: ')+m.subject.replace(/^(?:(?:Re|Fwd): )+/,''),forward:a==='mail-forward'?m.id:undefined,body:''});break;}
 case 'mail-send':sendMail();break;case 'chat-select':state.chat=b.dataset.id;openApp('chat');break;case 'oa-page':state.oaPage=b.dataset.page;refreshApp('oa');break;
 case 'browser-back':state.arc.historyIndex=Math.max(0,state.arc.historyIndex-1);refreshApp('browser');break;case 'browser-forward':state.arc.historyIndex=Math.min(state.arc.history.length-1,state.arc.historyIndex+1);refreshApp('browser');break;
 case 'theme':state.theme=b.dataset.theme;renderShell();refreshApp('break');break;case 'music':music();break;case 'coffee':state.coffee++;refreshApp('break');toast('咖啡好了',state.coffee>3?'这一杯换成低咖啡因。':'歇一会儿吧。');break;
 case 'cup':if(!state.cupFound){state.cupFound=true;notify('xiaoyu','杯子找到了，谢谢！原来是我浇绿萝后忘记拿走。咖啡算我的。','cup');refreshMany('break','chat');toast('杯子放回小雨桌上了');}break;
 case 'memory-flip':{const m=state.memory,i=Number(b.dataset.index);if(m.matched.includes(i)||m.open.includes(i))break;if(m.open.length===2)m.open=[];m.open.push(i);if(m.open.length===2){m.moves++;if(m.deck[m.open[0]]===m.deck[m.open[1]]){m.matched.push(...m.open);m.open=[];}}refreshApp('break');break;}
 case 'memory-reset':state.memory={deck:shuffle(['🌿','🌿','☕','☕','🍋','🍋','📎','📎','🍪','🍪','🌼','🌼']),moves:0,open:[],matched:[]};refreshApp('break');break;
 case 'end-day':endDay();break;case 'end-confirm':state.ended=true;state.arc.closed=true;closeModal();toast('今日记录已保存','可继续自由使用电脑，或下次继续查看。');break;case 'export':exportSave();break;case 'import':importSave();break;
 case 'reset-confirm':modal('<h2>重新开始罗青案例？</h2><p>将清除本版进度。旧剧情存档仍单独保留；可以先导出当前存档。</p><button class="btn danger" data-action="reset">确认重新开始</button><button class="btn" data-action="export">先导出</button><button class="btn" data-action="modal-close">取消</button>');break;
 case 'reset':localStorage.removeItem(KEY);location.reload();return;
 }save();});
